local a=require("ExcelTool")local b=a.Pack;local c=a.Sub;local d=a.LangGet;local e=a.Dmap;local f=require("Excels.Data.item_definition.skin")local g=f.tb;local h=f.get;g[404504]=b({e[21034],404504,8,81,247,"「差し入れは口実で、本当は猫目当てに来たんだろう。手触りの良い小動物に夢中になるのは人間の性というもの。だが、小動物を見るような目で俺を見るのはやめろ。俺は猫ではないし猫缶で買収されるわけもない。」",200045,2,"deco/character/a37_NP",false,false,1,false,false,false,false,"1",false,false,false,"100,-200,1",1828,801,432,1003,211,2128,2600,1003,516,2128,1261},h)g[404505]=b({e[24034],404505,3,54,248,"「暗闇にいる人間のための光明など、俺には……不要だ。そう、たとえ君がもたらす光でも。更なる深い闇に引きずり込まれたくなければ、今すぐ離れた方がいい……。」",200045,2,"deco/character/a37_WS",false,false,false,false,false,false,false,"1",false,"100,40,1","0,40,1","240,80,0.92","0,40,1","0,40,1","0,40,1",1876,879,382,707,397,2730,3326,707,573,2730,1261,1,2635,5000,1327,2529,5333,13666,7333,14000,20000,8000,5333},h)g[404601]=b({e[46057],404601,false,119,249,false,200046,false,"deco/character/jichuanxiang",302002,60,1,false,false,false,120,"0.959999978542328",false,false,false,false,false,false,false,"90,-200,1.04","210,40,0.96","20,20,0.96","210,40,0.96","20,20,0.96","0,0,0.96","180,50,0.96","140,50,0.96","180,50,0.96","140,50,0.96",false,1686,917,400,1151,619,1699,2378,1151,619,1699,1258,"jichuanxiang"},h)g[404602]=b({e[11034],404602,1,4,250,"「まったく、何っ回も負けてんのにま～た勝負を挑んで来るなんてな。今日は何で勝負する？ 『無敗の伝説』は伊達じゃないってわからせてやるよ！」",200046,1,"deco/character/jichuanxiang_0",302002,60,1842,873,400,1151,619,1520,2260,1151,619,1520,1214},h)g[404603]=b({e[13034],404603,5,67,251,"「響く鈴ども～！　準備はできてるかい？　そろそろ響様の【地上最強】新年配信が始まるぞー！　それじゃ一緒にカウントダウンをよろしく！　３――！　２――！　１―――！　ハッピーニューイヤー！！」",200046,2,"deco/character/404603",false,false,1,1,1845,890,398,1052,453,1843,2526,1052,588,1843,1261,1,5270,5000,2468,6652,6666,3666,4000,3166,10000,false,6666,false,false,0},h)g[404604]=b({e[21034],404604,15,120,252,"「ふふーん、世界一のボーカル様の初ライブへようこそ！　……コラ、最前列三番目のお前！　今話聞いてなかっただろ！　この後、響様のグッズ十個お買い上げな！　わかったか？」",200046,2,"deco/character/jichuanxiang_OX",false,false,1,false,false,false,false,"1",false,false,false,"240,-40,0.94",1890,885,398,831,415,2406,2837,831,583,2406,1261},h)g[404701]=b({e[17023],404701,false,121,253,false,200047,false,"deco/character/laien",302002,60,false,false,false,false,-275,"1","110,20,1","50,-40,1","100,-40,1",false,false,false,"0,-20,1","80,-20,1",false,false,false,1792,884,366,1110,450,1698,2940,1110,566,1698,1261},h)g[404702]=b({e[11034],404702,1,4,254,"「いいえ、まだ眠くありません。ただ、目が痒いだけです。\n本当です、もうちょっと遊べますよ。\nだから、僕を置いていかないでくださいね？ お姉さま……。」",200047,1,"deco/character/laien_0",302002,60,1775,869,399,939,728,2045,2093,939,728,2045,1101},h)g[404703]=b({e[12034],404703,4,107,255,"「しーっ。今はマジックタイムです、お静かに。一番好きなものを思い浮かべて下さい。…心の声、聞こえましたよ……箱を開けてみて下さい。……中身は僕でした～！　やっぱり、お姉さまが一番好きなのは僕だったんですね！」",200047,2,"deco/character/laien_SD",false,false,1,2021,980,398,1128,236,1677,2614,1128,678,1677,1261},h)g[404704]=b({e[21034],404704,3,24,256,"「ハロウィンのりんごは、色鮮やかなものほど毒があるって言われてるんです。お姉さまがくださるものなら、いただきますけど……あぁ、どんな風に起こしてもらえるんでしょう、ドキドキしちゃいます。」",200047,2,"deco/character/404704",false,false,false,false,false,false,false,false,false,"100,0,1",false,"100,-120,1",1894,891,396,814,699,2545,2369,814,699,2545,1150,1,3769,4173,2104,3618,8000,8500,16000,9667,13000,false,8000,false,false,0},h)g[404705]=b({e[9045],404705,2,72,257,"「お姉さま、まだ撮ってますか？ よかった、どうかそのままで。\nこの身に傷を負おうとも、必死にお姉さまの視界にいようとする僕の姿を、どうしても見てほしくて……\nこの動画をお姉さまが見返すたび、お姉さまの心が僕一人だけのものになっていくはず……そうですよね？」",200047,2,"deco/character/404705",1,3769,4173,2104,3618,8000,8500,16000,9667,13000,false,8000,"laien_xr",false,0},h)g[404801]=b({e[46057],404801,false,122,258,false,200048,false,"deco/character/senchuanlingzi",302002,60,1,false,false,false,34,"1",false,false,false,false,false,false,false,"120,-70,1.02",false,"-30,50,1",false,false,false,"0,40,1","0,40,1",false,false,false,1844,947,393,953,734,2014,2479,953,734,2014,1170,"senchuanlingzi"},h)